; Dated MCP forms retained as data; not a second test runner.
(def probe-forms
  {
   :turn-test-reds/settlement-candidate "(deftest settlement-mints-rows-for-unindexed-call-targets\n  ;; Resolvable calls point only at the complete program population.\n  ;; Unresolvable mentions settle as errors without inventing graph edges.\n  (support/with-database\n    (fn [connection]\n      (db/transact!\n       connection\n       [{:seon.ns/name 'my.macro-caller}\n        {:seon.agent/id \"macro-caller\"\n         :seon.agent/namespace [:seon.ns/name 'my.macro-caller]}])\n      (db/transact!\n       connection\n       (turn/system-run-tx\n        @connection\n        {:seon.agent/id \"macro-caller\" ::turn/id \"macro-call-run\" :seon.db.process/id \"macro-call-process\" :seon.turn/opened-tx \"datomic.tx\" ::turn/starting-ns [:seon.ns/name 'my.macro-caller] ::turn/sources [{:seon.cluster.eval/source \"(seon.bootstrap/help)\"}\n          {:seon.cluster.eval/source \"(missing.target/nope)\"}\n          {:seon.cluster.eval/source\n           \"(require 'unindexed.required)\"}]}))\n      (let [macro-row\n            (db/pull @connection\n                     [:db/id :seon.fn/source :seon.fn/macro?]\n                     [:seon.fn/sym \"seon.bootstrap/help\"])]\n        (is (:db/id macro-row) \"publication supplies the macro identity\")\n        (is (string? (:seon.fn/source macro-row)))\n        (is (true? (:seon.fn/macro? macro-row))))\n      (let [result\n            (db/transact!\n             connection\n             (turn/receipt-settle-tx\n              @connection\n              {::turn/id \"macro-call-run\"\n               :seon.cluster.eval/ordinal 0\n               :seon.eval/shown \"nil\"}))]\n        (is (not (:seon.error/kind result))\n            \"the settlement transaction commits\"))\n      (let [form (db/pull @connection\n                          [{:seon.fn/calls [:seon.fn/sym]}]\n                          [:seon.cluster.eval/id\n                           (turn/receipt-identity \"macro-call-run\" 0)])]\n        (is (= [{:seon.fn/sym \"seon.bootstrap/help\"}]\n               (:seon.fn/calls form))\n            \"the evaluation records its resolved call against the published identity\"))\n      (let [result\n            (db/transact!\n             connection\n             (turn/receipt-settle-tx\n              @connection\n              {::turn/id \"macro-call-run\"\n               :seon.cluster.eval/ordinal 1\n               :seon.cluster.eval/error \"Could not resolve missing.target/nope\"}))]\n        (is (not (:seon.error/kind result))\n            \"the error settlement commits without a dangling lookup ref\"))\n      (is (empty?\n           (db/q '[:find ?target\n                   :in $ ?form-id\n                   :where\n                   [?form :seon.cluster.eval/id ?form-id]\n                   [?form :seon.fn/calls ?target]]\n                 @connection\n                 (turn/receipt-identity \"macro-call-run\" 1)))\n          \"an unresolvable mention is not a call edge\")\n      (is (nil? (:db/id (db/pull @connection [:db/id]\n                                 [:seon.ns/name 'unindexed.required]))))\n      (let [result\n            (db/transact!\n             connection\n             (turn/receipt-settle-tx\n              @connection\n              {::turn/id \"macro-call-run\"\n               :seon.cluster.eval/ordinal 2\n               :seon.eval/shown \"nil\"\n               :seon.program/row\n               {:seon.ns/name 'my.macro-caller\n                :seon.ns/source \"(require 'unindexed.required)\"\n                :seon.ns/requires\n                #{[:seon.ns/name 'unindexed.required]}}}))]\n        (is (not (:seon.error/kind result))\n            \"the required namespace identity precedes its lookup ref\"))\n      (is (:db/id (db/pull @connection [:db/id]\n                           [:seon.ns/name 'unindexed.required]))\n          \"settlement mints the required namespace identity\"))))"
   :turn-test-reds/generated-scenario-candidate "(defn- generated-turn-agrees-with-durable-facts?\n  [scenario]\n  (with-cluster\n    (fn [cluster]\n      (let [{::keys [attempts succeeded?]} (expected-attempt-trace scenario)\n            connection (:seon.db/connection cluster)\n            retry-strategy {:seon.ai.retry/base-delay-ms 1\n                            :seon.ai.retry/multiplier 2.0\n                            :seon.ai.retry/jitter-fraction 0.0\n                            :seon.ai.retry/maximum-delay-ms 4\n                            :seon.ai.retry/maximum-retries\n                            (::maximum-retries scenario)\n                            :seon.ai.retry/maximum-total-delay-ms 1000}\n            completions (mapv turn-completion (::outcomes scenario))\n            requests (atom [])\n            committed-prefixes (atom [])\n            complete! (fn [request]\n                        (swap! committed-prefixes\n                               conj\n                               (mapv actual-attempt-shape\n                                     (attempt-rows @connection)))\n                        (let [ordinal (count @requests)]\n                          (swap! requests conj request)\n                          (nth completions ordinal (last completions))))]\n        (let [report (db/transact!\n         connection\n         [(cond-> {:db/id [:seon.config/cluster \"turn-test\"]\n                   :seon.config.ai.retry/base-delay-ms\n                   (:seon.ai.retry/base-delay-ms retry-strategy)\n                   :seon.config.ai.retry/multiplier\n                   (:seon.ai.retry/multiplier retry-strategy)\n                   :seon.config.ai.retry/jitter-fraction\n                   (:seon.ai.retry/jitter-fraction retry-strategy)\n                   :seon.config.ai.retry/maximum-delay-ms\n                   (:seon.ai.retry/maximum-delay-ms retry-strategy)\n                   :seon.config.ai.retry/maximum-retries\n                   (:seon.ai.retry/maximum-retries retry-strategy)\n                   :seon.config.ai.retry/maximum-total-delay-ms\n                   (:seon.ai.retry/maximum-total-delay-ms retry-strategy)}\n            (::backup? scenario)\n            (assoc :seon.config.ai.backup/endpoint\n                   (:seon.ai/endpoint backup-target)\n                   :seon.config.ai.backup/model\n                   (:seon.ai/model backup-target)\n                   :seon.config.ai.backup/api-key-variable\n                   (:seon.ai/api-key-variable backup-target)\n                   :seon.config.ai.backup/timeout-ms\n                   (:seon.ai/timeout-ms backup-target)))])]\n          (when (:seon.error/kind report)\n            (throw (ex-info \"The generated scenario seed was refused.\" report))))\n        (with-redefs [ai/complete complete!]\n          (drive! cluster 12))\n        (let [rows (attempt-rows @connection)\n              actual (mapv actual-attempt-shape rows)\n              run-row (db/q '[:find (pull ?run [*]) .\n                             :where [?run :seon.turn/attempts _]]\n                           @connection)]\n          (and\n           (= attempts actual)\n           (= (mapv #(subvec attempts 0 %)\n                    (range (count attempts)))\n              @committed-prefixes)\n           (= (mapv ::model attempts)\n              (mapv #(if (= \"backup-probe\" (:seon.ai/model %))\n                       :backup\n                       :primary)\n                    @requests))\n           (= (vec (range (count rows)))\n              (mapv :seon.ai.attempt/ordinal rows))\n           (every? #(not (contains? % :seon.ai/disposition)) rows)\n           (contains? run-row :seon.turn/closed-tx)\n           (= 1 (turn/episode-runs @connection \"agent-a\"))\n           (= succeeded?\n              (contains? run-row :seon.turn/reply-size))))))))"
   :turn-test-reds/baseline "(def turn-reds-b28 (future (#'seon.test/with-test-loader (fn [] (require 'seon.turn-test :reload) (mapv (fn [s] (seon.test/run (#'seon.test/resolve-test s) (seon.operator/connection \"default\"))) '[seon.turn-test/settlement-mints-rows-for-unindexed-call-targets seon.turn-test/virtual-turns-use-the-proc-and-compaction-is-agent-scoped])))))"
   :turn-test-reds/bounded-virtual-baseline "(def turn-reds-b28-virtual (future (let [c (seon.operator/connection \"default\")] (seon.test/run (#'seon.test/resolve-test 'seon.turn-test/virtual-turns-use-the-proc-and-compaction-is-agent-scoped) c {:seon.test/remaining-ms 120000 :seon.test.run/provenance (seon.test.runner/provenance (seon.db/db c))}))))"
   :turn-test-reds/contract-comparison "(#'seon.test/with-test-loader (fn [] (let [c (seon.operator/connection \"default\") fields [:seon.fn/spec] ident [:seon.fn/sym \"seon.test/stale\"]] {:turn-test-reds/default (seon.db/pull (seon.db/db c) fields ident) :turn-test-reds/fixture (seon.test-support/with-database (fn [f] (seon.db/pull @f fields ident)))})))"})
